// Watch opens a long-lived watch on SysORTable.
//
// cols selects the columns whose values are reported on every emitted
// event. opts override cadence bounds, per-column tier classifications,
// fallback behavior, and other policy — see [snmp.WatchOption] for the
// full set.
//
// cols is a slice rather than variadic because opts is variadic and
// Go forbids two variadic parameters.
//
// Events emitted on this stream:
//   - ChangeKindAdded    — Row populated, Prev always nil.
//   - ChangeKindModified — Row is current state. Prev is nil unless
//     the caller passed [snmp.WithPrevRow]; when
//     set, Prev carries the previous Row.
//   - ChangeKindRemoved  — Row carries the last-known state at the
//     time the row disappeared. Prev is nil.
//
// The returned Watcher must be Closed when the caller is done; iteration
// exit alone does not free the underlying goroutine until Close.
//
// On validation failure (invalid cadence bounds, tier override of the
// indicator column, etc.) Watch returns a Watcher whose Err() returns
// the cause immediately; range loops exit without emitting events and
// Close is a no-op.
func (sysORTableT) Watch(ctx context.Context, sess snmp.Session, cols []snmp.AnyColumn, opts ...snmp.WatchOption) *SysORTableWatcher {
	allOpts := append([]snmp.WatchOption{snmp.WithTierLookup(ColumnTier)}, opts...)
	w, _ := snmp.NewWatcher[SysORTableRow](ctx, sess, SysORTableIndicator, cols, decodeSysORTableRow, equalSysORTableRow, mergeSysORTableRow, allOpts...)

	return &SysORTableWatcher{w: w}
}

// sNMPv2MIBOIDDispatch maps column wire keys ([snmp.OID.WireKey]) to their
// typed AnyColumn for fast
// lookup during table-walk decoding. Per-MIB-module — no global
// registry; cross-package callers should consult OIDDispatch().
var sNMPv2MIBOIDDispatch = map[string]snmp.AnyColumn{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 2).WireKey(): SysORID,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 3).WireKey(): SysORDescr,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 4).WireKey(): SysORUpTime,
}

// OIDDispatch returns a shallow copy of the package's wire-key →
// AnyColumn map. The copy isolates callers from accidental mutation
// of the package-internal map (#12).
func OIDDispatch() map[string]snmp.AnyColumn {
	out := make(map[string]snmp.AnyColumn, len(sNMPv2MIBOIDDispatch))
	for k, v := range sNMPv2MIBOIDDispatch {
		out[k] = v
	}
	return out
}

// sNMPv2MIBColumnTiers maps column wire keys ([snmp.OID.WireKey]) to their
// snmp.Tier classification.
// Tier classification drives the Watcher's scheduler — counters fire
// on their own cadence, state columns refresh on indicator advance,
// and indicator columns drive the change-detection probe itself.
// See snmp.Tier and snmp.Watcher for the consumption contract.
var sNMPv2MIBColumnTiers = map[string]snmp.Tier{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 2).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 3).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 4).WireKey(): snmp.TierIndicator,
}

// ColumnTier returns the codegen-classified [snmp.Tier] for col, or
// snmp.TierUnknown when col's OID is not known to this package. The
// generated Watch methods install this function via
// [snmp.WithTierLookup]; returning TierUnknown lets the runtime fall
// back to its wire-Kind heuristic for columns this package does not
// classify. Caller overrides via [snmp.WithColumnTier] still win.
func ColumnTier(col snmp.AnyColumn) snmp.Tier {
	if col == nil {
		return snmp.TierUnknown
	}
	t, ok := sNMPv2MIBColumnTiers[col.Key()]
	if !ok {
		return snmp.TierUnknown
	}
	return t
}

